-- ============================================
-- LUMA — Thème 17 : MOYEN 2/3 x4 — Suivre un cours collectif pour la première fois
-- ============================================


update scenarios set content = '{"characters": {"instructor": "l''animatrice du cours", "classmate": "un autre participant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "instructor", "text": "First time in a spin class? Don''t worry, go at your own pace.", "text_fr": "Première fois en cours de spinning ? T''inquiète pas, va à ton propre rythme.", "choices": [{"text": "Thanks, I''m a bit nervous but excited to try.", "text_fr": "Merci, je suis un peu nerveux mais excité d''essayer.", "next": "n2"}, {"text": "I''ll do my best to keep up with everyone.", "text_fr": "Je vais faire de mon mieux pour suivre tout le monde.", "next": "n2b"}]}, "n2": {"speaker": "instructor", "text": "That''s the spirit! Everyone here started as a beginner too.", "text_fr": "Voilà le bon esprit ! Tout le monde ici a commencé en débutant aussi.", "choices": [{"text": "That''s reassuring, thank you.", "text_fr": "C''est rassurant, merci.", "next": "n3"}]}, "n2b": {"speaker": "instructor", "text": "No need to keep up with anyone, this is about your own progress.", "text_fr": "Pas besoin de suivre qui que ce soit, il s''agit de ta propre progression.", "choices": [{"text": "That''s a good mindset, I''ll remember that.", "text_fr": "C''est un bon état d''esprit, je vais m''en souvenir.", "next": "n3"}]}, "n3": {"speaker": "instructor", "text": "Let''s adjust your bike setup first, proper form matters a lot here.", "text_fr": "Ajustons d''abord la configuration de ton vélo, la bonne posture compte beaucoup ici.", "choices": [{"text": "Sounds good, I want to make sure I''m doing this right.", "text_fr": "Ça marche, je veux m''assurer de bien faire ça.", "next": "n4"}]}, "n4": {"speaker": "classmate", "text": "(Nearby) First class? I remember mine, I was so out of breath by the end!", "text_fr": "(À proximité) Premier cours ? Je me souviens du mien, j''étais tellement essoufflé à la fin !", "choices": [{"text": "Ha, good to know I''m not alone in that experience!", "text_fr": "Ha, content de savoir que je suis pas seul dans cette expérience !", "next": "n5"}]}, "n5": {"speaker": "instructor", "text": "(Mid-class) You''re doing great, keep that pace steady!", "text_fr": "(En plein cours) Tu te débrouilles très bien, garde ce rythme stable !", "choices": [{"text": "(Push through, feeling the burn but determined to finish strong.)", "text_fr": "(Continue, sentant la brûlure mais déterminé à finir fort.)", "next": "n6"}]}, "n6": {"speaker": "instructor", "text": "(after class) You did amazing for a first timer!", "text_fr": "(après le cours) T''as été génial pour une première fois !", "choices": [{"text": "Thank you, I really enjoyed it, I''ll be back!", "text_fr": "Merci, j''ai vraiment aimé, je reviendrai !", "next": "n7"}]}, "n7": {"speaker": "classmate", "text": "See you next class then! It gets easier, I promise.", "text_fr": "À la prochaine alors ! Ça devient plus facile, promis.", "choices": [{"text": "Looking forward to it, thanks for the encouragement!", "text_fr": "J''ai hâte, merci pour l''encouragement !", "next": "end_success"}]}, "end_success": {"speaker": "instructor", "text": "Can''t wait to see you at the next class!", "text_fr": "J''ai hâte de te revoir au prochain cours !", "end": true, "ending_label": "Premier cours collectif réussi avec brio 🚴💪"}}}'::jsonb, is_playable = true
where title = 'Suivre un cours collectif pour la première fois'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
